class InsufficientFundsException extends Exception {
    private final double deficit;

    public InsufficientFundsException(String message, double deficit) {
        super(message);
        this.deficit = deficit;
    }

    public double getDeficit() {
        return deficit;
    }
}

public class CustomExceptionDemo {
    public static void withdraw(double balance, double amount) throws InsufficientFundsException {
        if (amount > balance) {
            throw new InsufficientFundsException("Cannot withdraw funds", amount - balance);
        }
        System.out.println("Withdrawal successful. Remaining: " + (balance - amount));
    }

    public static void main(String[] args) {
        try {
            withdraw(100.0, 150.0);
        } catch (InsufficientFundsException e) {
            System.out.println("Caught Custom Exception: " + e.getMessage());
            System.out.println("Shortfall amount: $" + e.getDeficit());
        }
    }
}

