class ConfigurationException extends Exception {
    public ConfigurationException(String message, Throwable cause) {
        super(message, cause);
    }
}

public class ConfigLoader {
    public static int loadPort(String raw) throws ConfigurationException {
        try {
            return Integer.parseInt(raw);
        } catch (NumberFormatException e) {
            throw new ConfigurationException("Failed to load port configuration", e);
        }
    }

    public static void main(String[] args) {
        try {
            loadPort("invalid_port");
        } catch (ConfigurationException e) {
            System.out.println("Message: " + e.getMessage());
            System.out.println("Root Cause: " + e.getCause().getClass().getSimpleName());
        }
    }
}

