abstract class ServiceException extends Exception {
    public ServiceException(String msg) { super(msg); }
}
class RetryableException extends ServiceException {
    public RetryableException(String msg) { super(msg); }
}
class FatalException extends ServiceException {
    public FatalException(String msg) { super(msg); }
}

public class RetryExecutor {
    static int attempts = 0;
    public static void executeService() throws ServiceException {
        attempts++;
        if (attempts < 2) {
            throw new RetryableException("Connection timeout");
        }
        System.out.println("Service succeeded on attempt: " + attempts);
    }

    public static void main(String[] args) {
        int maxRetries = 3;
        for (int i = 0; i < maxRetries; i++) {
            try {
                executeService();
                break;
            } catch (RetryableException e) {
                System.out.println("Retryable error: " + e.getMessage() + ". Retrying...");
            } catch (FatalException e) {
                System.out.println("Fatal error: " + e.getMessage() + ". Aborting.");
                break;
            } catch (ServiceException e) {
                System.out.println("Service error: " + e.getMessage());
                break;
            }
        }
    }
}

