practiceProblems.solution:
public class StackSanitizer {
    public static String sanitize(Throwable t) {
        if (t == null) return "";
        return t.getClass().getSimpleName() + ": " + (t.getMessage() != null ? t.getMessage() : "No message");
    }

    public static void main(String[] args) {
        Exception ex = new IllegalArgumentException("Invalid account number");
        System.out.println(sanitize(ex));
    }
}
